class Solution {
    static int next(int n) {
        int s = 0;
        while (n) {
            int d = n % 10;
            s += d * d;
            n /= 10;
        }
        return s;
    }
public:
    bool isHappy(int n) {
        unordered_set<int> seen;
        while (n != 1 && !seen.count(n)) {
            seen.insert(n);
            n = next(n);
        }
        return n == 1;
    }
};

