        // 双向映射，防止两个字母映射到同一字符
        vector<int> m1(256, -1), m2(256, -1);
        for (int i = 0; i < (int)s.size(); i++) {
            int a = (unsigned char)s[i], b = (unsigned char)t[i];
            if (m1[a] == -1 && m2[b] == -1) { m1[a] = b; m2[b] = a; }
            else if (m1[a] != b || m2[b] != a) return false;
        }
        return true;
    }
};

