            for (char ch : words[k]) cur[ch - 'a']++;
            for (int i = 0; i < 26; i++)
                if (cur[i] < base[i]) base[i] = cur[i];
        }
        vector<string> res;
        for (int i = 0; i < 26; i++)
            for (int t = 0; t < base[i]; t++) res.push_back(string(1, 'a' + i));
        return res;
    }
};

